<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">    token_limit </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> token_limit </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">or</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> int</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(context_window </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">*</span><span style="--shiki-light:#383A42;--shiki-dark:#D19A66;"> DEFAULT_TOKEN_LIMIT_RATIO</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
